import heapq

def match(orders):
    buy_heap = []  # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    order_info = {}
    seq = 0
    trades = []

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info and info['status'] == 'active':
                info['status'] = 'cancelled'
            continue

        if typ == 'limit' or typ == 'ioc':
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        order_info[oid] = {'side': side, 'price': price, 'qty': qty, 'status': 'pending', 'type': typ}
        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            top_id = top[2]
            top_info = order_info.get(top_id)
            if top_info is None or top_info['status'] != 'active':
                heapq.heappop(opp_heap)
                continue
            top_price = top_info['price']

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            match_qty = min(remaining, top_info['qty'])
            if side == 'buy':
                trades.append([oid, top_id, top_price, match_qty])
            else:
                trades.append([top_id, oid, top_price, match_qty])

            remaining -= match_qty
            top_info['qty'] -= match_qty

            if top_info['qty'] == 0:
                top_info['status'] = 'filled'
                heapq.heappop(opp_heap)

        order_info[oid]['qty'] = remaining

        if remaining > 0 and typ == 'limit':
            order_info[oid]['status'] = 'active'
            seq += 1
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            order_info[oid]['status'] = 'filled'

    return trades

